  "wh3_dlc29_spell_undeath_khizaar_the_soulstealer": {"id":"wh3_dlc29_spell_undeath_khizaar_the_soulstealer","name":"The Soulstealer","description":"Undeath beckons a soul to return from the afterlife. Those who know such forces also know the living, too, can be forced to give up their souls.","icon":"ui/battle ui/ability_icons/wh3_dlc29_spell_undeath_khizaar_the_soulstealer.png","mana_cost":10,"normal":{"id":"wh3_dlc29_spell_undeath_khizaar_the_soulstealer","name":"The Soulstealer","phases":[{"id":"wh3_dlc29_spell_undeath_khizaar_the_soulstealer","duration":11,"effects":[],"dot":{"damage_per_tick":4,"chance":1,"max_entities":25,"frequency":1,"duration":11}}]},"overcast":{"id":"wh3_dlc29_spell_undeath_khizaar_the_soulstealer_upgraded","name":"Undeath Khizaar The Soulstealer Upgraded","phases":[{"id":"wh3_dlc29_spell_undeath_khizaar_the_soulstealer_upgraded","duration":22,"effects":[],"dot":{"damage_per_tick":4,"chance":1,"max_entities":25,"frequency":1,"duration":22}}]}},
