  "wh3_dlc29_spell_undeath_sulekhim_hand_of_dust": {"id":"wh3_dlc29_spell_undeath_sulekhim_hand_of_dust","name":"The Hand of Dust","description":"Seconds and centuries are all the same to a master of Shyish. All that is transient is at his mercy. It fades and crumbles at his touch.","icon":"ui/battle ui/ability_icons/wh3_dlc29_spell_undeath_sulekhim_hand_of_dust.png","mana_cost":3,"normal":{"id":"wh3_dlc29_spell_undeath_sulekhim_hand_of_dust","name":"The Hand of Dust","phases":[{"id":"wh3_dlc29_spell_undeath_sulekhim_hand_of_dust","duration":14,"effects":["wh3_dlc29_spell_undeath_sulekhim_hand_of_dust"]}]},"overcast":{"id":"wh3_dlc29_spell_undeath_sulekhim_hand_of_dust_upgraded","name":"Undeath Sulekhim Hand Of Dust Upgraded","phases":[{"id":"wh3_dlc29_spell_undeath_sulekhim_hand_of_dust_upgraded","duration":14,"effects":["wh3_dlc29_spell_undeath_sulekhim_hand_of_dust_upgraded"]}]}},
  "wh3_main_spell_great_maw_braingobbler": {"id":"wh3_main_spell_great_maw_braingobbler","name":"Braingobbler","description":"The spellcaster chomps through a severed skull, gobbling up the brain and projecting the decapitated victim's worst nightmares into enemies' minds, sapping their will to fight on.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_braingobbler.png","mana_cost":4,"normal":{"id":"wh3_main_spell_great_maw_braingobbler","name":"Braingobbler","phases":[{"id":"wh3_main_spell_great_maw_braingobbler","duration":18,"effects":[]}]},"overcast":{"id":"wh3_main_spell_great_maw_braingobbler_upgraded","name":"Braingobbler Upgraded","phases":[{"id":"wh3_main_spell_great_maw_braingobbler_upgraded","duration":36,"effects":[]}]}},
  "wh3_main_spell_great_maw_bullgorger": {"id":"wh3_main_spell_great_maw_bullgorger","name":"Bullgorger","description":"Devouring the heart of a bull Rhinox or Mournfang, raw vitality is projected into the Great Maw, increasing the ferocity of the Ogres' attacks.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_bullgorger.png","mana_cost":4,"normal":{"id":"wh3_main_spell_great_maw_bullgorger","name":"Bullgorger","phases":[{"id":"wh3_main_spell_great_maw_bullgorger","duration":17,"effects":["wh3_main_spell_great_maw_bullgorger"]}]},"overcast":{"id":"wh3_main_spell_great_maw_bullgorger_upgraded","name":"Bullgorger Upgraded","phases":[{"id":"wh3_main_spell_great_maw_bullgorger_upgraded","duration":34,"effects":["wh3_main_spell_great_maw_bullgorger_upgraded"]}]}},
  "wh3_main_spell_great_maw_toothcracker": {"id":"wh3_main_spell_great_maw_toothcracker","name":"Toothcracker","description":"By consuming a hunk of tooth-breaking granite, the spellcaster bestows the rock's resilience and the sturdiness of the mountains themselves into his brethren.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_toothcracker.png","mana_cost":6,"normal":{"id":"wh3_main_spell_great_maw_toothcracker","name":"Toothcracker","phases":[{"id":"wh3_main_spell_great_maw_toothcracker","duration":35,"effects":["wh3_main_spell_great_maw_toothcracker"]}]},"overcast":{"id":"wh3_main_spell_great_maw_toothcracker_upgraded","name":"Toothcracker Upgraded","phases":[{"id":"wh3_main_spell_great_maw_toothcracker_upgraded","duration":60,"effects":["wh3_main_spell_great_maw_toothcracker_upgraded"]}]}},
