  "wh3_main_spell_slaanesh_acquiescence": {"id":"wh3_main_spell_slaanesh_acquiescence","name":"Acquiescence","description":"The spellcaster's corrupting touch puts their victims into a blissful, euphoric state for a short time, rendering them little able to move, let alone defend themselves.","icon":"ui/battle ui/ability_icons/wh3_main_spell_slaanesh_acquiescence.png","mana_cost":6,"normal":{"id":"wh3_main_spell_slaanesh_acquiescence","name":"Acquiescence","phases":[{"id":"wh3_main_spell_slaanesh_acquiescence","duration":25,"effects":["wh3_main_spell_slaanesh_acquiescence"]}]},"overcast":{"id":"wh3_main_spell_slaanesh_acquiescence_upgraded","name":"Acquiescence Upgraded","phases":[{"id":"wh3_main_spell_slaanesh_acquiescence_upgraded","duration":25,"effects":["wh3_main_spell_slaanesh_acquiescence_upgraded"]}]}},
